//partly based on the Meshless Voronoi on the GPU
//https://inria.hal.science/hal-01927559v1/file/voroGPU.pdf

#define MAX_SITES 100  // Changed to 150
#define MAX_STEPS 50
#define MIN_DIST 0.002
#define MAX_DIST 50.0
#define EPSILON 0.002
#define CELL_TRANSPARENCY 0.1
#define AUTO_ROTATE_SPEED 0.1
#define CUBE_SIZE 1.0
#define MAX_SITES_PER_CELL 16

// Precomputed constants
const vec3 CUBE_SIZE_VEC = vec3(CUBE_SIZE);
const vec3 NEG_CUBE_SIZE_VEC = vec3(-CUBE_SIZE);

struct Site {
    vec3 pos;
    float weight;
};

// Grid structure with fixed size arrays
struct GridCell {
    int count;
    int sites[MAX_SITES_PER_CELL];
};

Site sites[MAX_SITES];
GridCell grid[27];  // Fixed size 3x3x3 grid = 27 cells

vec3 hash33(vec3 p3) {
    p3 = fract(p3 * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz + 19.19);
    return -1.0 + 2.0 * fract((p3.xxy + p3.yzz) * p3.zyx);
}

ivec3 posToGrid(vec3 pos) {
    return clamp(ivec3((pos / CUBE_SIZE + 1.0) * 0.5 * 3.0), 
                ivec3(0), ivec3(2));  // 3x3x3 grid so max index is 2
}

int gridIndex(ivec3 pos) {
    return pos.x + 3 * (pos.y + 3 * pos.z);  // Fixed 3x3x3 grid indexing
}

void initGrid() {
    for(int i = 0; i < 27; i++) {  // Fixed size iteration
        grid[i].count = 0;
    }

    for(int i = 0; i < MAX_SITES; i++) {
        ivec3 cell = posToGrid(sites[i].pos);
        int idx = gridIndex(cell);
        if(grid[idx].count < MAX_SITES_PER_CELL) {
            grid[idx].sites[grid[idx].count] = i;
            grid[idx].count++;
        }
    }
}

void initSites() {
    float timeScale = iTime * 0.1;
    for(int i = 0; i < MAX_SITES; i++) {
        float fi = float(i);
        vec3 basePos = hash33(vec3(fi * 0.0573, fi * 0.0731, fi * 0.0917));
        vec3 movement = vec3(
            sin(timeScale + fi * 0.1),
            cos(timeScale * 0.7 + fi * 0.2),
            sin(timeScale * 1.1 + fi * 0.15)
        ) * 0.1;
        sites[i].pos = clamp(basePos + movement, vec3(-0.9), vec3(0.9)) * CUBE_SIZE;
    }
    initGrid();
}

void getCellInfo(vec3 p, out float minDist, out int cellId, out float secondMinDist) {
    minDist = MAX_DIST;
    secondMinDist = MAX_DIST;
    cellId = -1;

    ivec3 gridPos = posToGrid(p);

    for(int dx = -1; dx <= 1; dx++) {
        for(int dy = -1; dy <= 1; dy++) {
            for(int dz = -1; dz <= 1; dz++) {

                ivec3 cell = gridPos + ivec3(dx, dy, dz);
                if(any(lessThan(cell, ivec3(0))) || any(greaterThanEqual(cell, ivec3(3)))) 
                    continue;

                int idx = gridIndex(cell);
                for(int i = 0; i < grid[idx].count; i++) {
                    int siteId = grid[idx].sites[i];
                    vec3 sitePos = sites[siteId].pos;

                    float d = length(p - sitePos);
                    if(d < minDist) {
                        secondMinDist = minDist;
                        minDist = d;
                        cellId = siteId;
                    } else if(d < secondMinDist) {
                        secondMinDist = d;
                    }
                }
            }
        }
    }
}


vec2 cubeIntersection(vec3 ro, vec3 rd) {
    vec3 inv_dir = 1.0 / rd;
    vec3 t1 = (NEG_CUBE_SIZE_VEC - ro) * inv_dir;
    vec3 t2 = (CUBE_SIZE_VEC - ro) * inv_dir;
    vec3 tmin = min(t1, t2);
    vec3 tmax = max(t1, t2);
    return vec2(max(max(tmin.x, tmin.y), tmin.z),
                min(min(tmax.x, tmax.y), tmax.z));
}

vec4 getCellColor(int id, float alpha) {
    float hue = float(id) * 0.0873;
    vec3 color = 0.5 + 0.5 * cos(6.28318 * (vec3(0.0, 0.33, 0.67) + hue));
    return vec4(color, alpha);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    initSites();

    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float zoom = clamp(3.0 - (iMouse.y / iResolution.y) * 1.5, 1.5, 3.0);

    float angle = iMouse.z > 0.0 ? 
        iMouse.x / iResolution.x * 6.28318 : 
        iTime * AUTO_ROTATE_SPEED;
    vec3 ro = vec3(
        zoom * sin(angle),
        zoom * 0.5,
        zoom * cos(angle)
    );
    vec3 lookAt = vec3(0.0);
    vec3 forward = normalize(lookAt - ro);
    vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), forward));
    vec3 up = cross(forward, right);
    vec3 rd = normalize(mat3(right, up, forward) * vec3(uv, 1.0));

    vec2 cube_t = cubeIntersection(ro, rd);

    vec3 backgroundColor = mix(
        vec3(0.3),
        vec3(0.015),
        clamp(1.0 - (uv.y * 0.5 + 0.5), 0.0, 1.0)
    );
    vec4 finalColor = vec4(backgroundColor, 1.0);

    if(cube_t.x < cube_t.y && cube_t.y > 0.0) {
        float t = max(0.0, cube_t.x);
        vec3 pos = ro + rd * t;

        int cellId;
        float minDist, secondMinDist;
        getCellInfo(pos, minDist, cellId, secondMinDist);

        vec4 acc = vec4(0.0);
        float t_end = min(cube_t.y, t + 2.0);

        for(int i = 0; i < MAX_STEPS && t < t_end; i++) {
            if(acc.a >= 0.98) break;

            getCellInfo(pos, minDist, cellId, secondMinDist);
            float boundaryDist = abs(secondMinDist - minDist);
            float stepSize = max(boundaryDist * 0.5, 0.02);

            if(boundaryDist < 0.02) {
                vec4 cellColor = getCellColor(cellId, CELL_TRANSPARENCY);
                float alpha = (1.0 - acc.a) * cellColor.a;
                acc += vec4(cellColor.rgb * alpha, alpha);
            }

            t += stepSize;
            pos = ro + rd * t;
        }

        if(acc.a > 0.0) {
            finalColor = mix(finalColor, vec4(acc.rgb / acc.a, acc.a), acc.a);
        }
    }

    fragColor = finalColor;
}
